function buildExpectedMeasurements(specKey, headType){
  const s=burnerSpecLibrary[specKey];
  if(!s)return {};
  let measureD="";
  if(headType==="TL")measureD=s.D1||s.DM||s.D||"";
  else if(headType==="TM")measureD=s.DM||s.D1||s.D||"";
  else if(headType==="TC")measureD=s.D||"";
  else measureD=[s.D,s.DM,s.D1].filter(Boolean).join(" / ");
  return {
    measureG:s.G||"",measureF:s.F||"",measureL:s.L||"",measureI:s.I||"",measureM:s.M||"",measureD,
    plateThickness:s.plate||""
  };
}

