class ReportDB {
  constructor(){this.db=null}
  async open(){
    if(this.db)return this.db;
    this.db=await new Promise((resolve,reject)=>{
      const req=indexedDB.open("enorpaBurnerReports",1);
      req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains("reports"))db.createObjectStore("reports",{keyPath:"id"})};
      req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)
    });
    return this.db
  }
  async put(record){const db=await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction("reports","readwrite");tx.objectStore("reports").put(record);tx.oncomplete=()=>resolve(record);tx.onerror=()=>reject(tx.error)})}
  async all(){const db=await this.open();return new Promise((resolve,reject)=>{const req=db.transaction("reports").objectStore("reports").getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)));req.onerror=()=>reject(req.error)})}
  async get(id){const db=await this.open();return new Promise((resolve,reject)=>{const req=db.transaction("reports").objectStore("reports").get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async delete(id){const db=await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction("reports","readwrite");tx.objectStore("reports").delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
}
const db=new ReportDB();

function show(id){screens.forEach(s=>s.classList.toggle("active",s.id===id));window.scrollTo(0,0)}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function attr(v){return esc(v)}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2400)}
function activeSteps(){return steps.filter(s=>{if(s.fuel&&!s.fuel.includes(state.template.fuel))return false;if(s.depends&&state.values[s.depends[0]]!==s.depends[1])return false;if(state.template.fuel==="gas-basic"&&["gasSerial","gasChecklist","rwfPhoto","pt100Check","pt100Photo","gasSetCheck","gasSetPhoto","filterPhoto","liquidChecklist"].includes(s.id))return false;return true})}
function newId(){return crypto.randomUUID?crypto.randomUUID():"r-"+Date.now()+"-"+Math.random().toString(16).slice(2)}
function reportNo(){const y=new Date().getFullYear();const n=Number(localStorage.getItem("enorpaReportSequence")||0)+1;localStorage.setItem("enorpaReportSequence",n);return `ENR-${y}-${String(n).padStart(6,"0")}`}

function brandCounts(){
  return burnerTemplates.filter(t=>!t.hidden).reduce((acc,t)=>{acc[t.brand]=(acc[t.brand]||0)+1;return acc},{});
}
function renderBrands(){
  const counts=brandCounts();
  const brands=["Ecoflam","Baltur"];
  $("#brandList").innerHTML=brands.map(brand=>`<button class="brand-card" data-brand="${attr(brand)}"><span class="brand-monogram">${brand.slice(0,2).toUpperCase()}</span><span><strong>${esc(brand)}</strong><small>${counts[brand]||0} brülör modeli</small></span><span>›</span></button>`).join("");
  document.querySelectorAll("[data-brand]").forEach(button=>button.onclick=()=>{
    state.selectedBrand=button.dataset.brand;
    $("#selectedBrandName").textContent=`${state.selectedBrand} brülörleri`;
    $("#templateSearch").value="";
    show("templates");
    renderTemplates();
  });
}
function renderTemplates(){
  const brand=state.selectedBrand;
  const query=($("#templateSearch")?.value||"").trim().toLocaleLowerCase("tr-TR");
  const selectedSeries=$("#seriesFilter")?.value||"all";
  let rows=burnerTemplates.filter(t=>!t.hidden&&(!brand||t.brand===brand));
  const series=[...new Set(rows.map(t=>t.series))].sort((a,b)=>a.localeCompare(b,"tr"));
  if($("#seriesFilter")){
    const previous=$("#seriesFilter").value||"all";
    $("#seriesFilter").innerHTML=`<option value="all">Tüm seriler</option>${series.map(s=>`<option value="${attr(s)}">${esc(s)}</option>`).join("")}`;
    $("#seriesFilter").value=series.includes(previous)?previous:"all";
  }
  const activeSeries=$("#seriesFilter")?.value||selectedSeries;
  if(activeSeries!=="all")rows=rows.filter(t=>t.series===activeSeries);
  if(query)rows=rows.filter(t=>`${t.title} ${t.code} ${t.series}`.toLocaleLowerCase("tr-TR").includes(query));
  rows.sort((a,b)=>a.series.localeCompare(b.series,"tr")||a.title.localeCompare(b.title,"tr",{numeric:true}));
  $("#templateCount").textContent=`${rows.length} model gösteriliyor`;
  const icons={MULTICALOR:"MC",BLU:"BL",OILFLAM:"OF","MAX GAS":"MG",TBML:"TB",TBG:"TG",GENEL:"GN"};
  const grouped=rows.reduce((acc,t)=>{(acc[t.series]??=[]).push(t);return acc},{});
  $("#templateList").innerHTML=rows.length?Object.entries(grouped).map(([seriesName,items])=>`<section class="series-block"><div class="series-heading"><strong>${esc(seriesName)}</strong><span>${items.length} model</span></div><div class="template-grid">${items.map(t=>`<button class="template-card" data-template="${t.id}"><span class="template-icon">${icons[t.family]||"BR"}</span><span><strong>${esc(t.title)}</strong><small>Kod: ${esc(t.code||"manuel girilecek")} · ${esc(t.dataStatus)}</small></span><span>›</span></button>`).join("")}</div></section>`).join(""):`<div class="empty-state">Aramaya uygun brülör bulunamadı.</div>`;
  document.querySelectorAll("[data-template]").forEach(b=>b.onclick=()=>startTemplate(b.dataset.template));
}
async function startTemplate(id){
  state.template=getTemplateById(id);
  if(state.template.drawingFileId&&!state.template.remoteDrawingDataUrl){
    toast("Ölçü görseli hazırlanıyor…");
    try{state.template.remoteDrawingDataUrl=await loadCatalogFileAsDataUrl(state.template.drawingFileId)}catch(error){console.warn("Ölçü görseli alınamadı",error)}
  }
  state.stepIndex=0;state.values={burnerBrand:state.template.brand||"",burnerSeries:state.template.series||"",burnerName:state.template.title,burnerModel:state.template.code,inspector:"Ferhat HACIOSMANOĞLU",inspectionResult:"Kontrolden geçti"};state.photos={};state.recordId=newId();state.reportNo=reportNo();state.status="draft";show("flow");renderFlow();if(state.template.datasheetWarning)setTimeout(()=>alert(state.template.datasheetWarning),150)
}
async function resumeRecord(id){const r=await db.get(id);if(!r)return;state.template=getTemplateById(r.templateId);state.stepIndex=r.stepIndex||0;state.values=r.values||{};state.photos=r.photos||{};state.recordId=r.id;state.reportNo=r.reportNo;state.status=r.status;show(r.status==="draft"?"flow":"record");if(r.status==="draft")renderFlow();else renderRecord(r)}
function renderFlow(){
  const list=activeSteps();if(state.stepIndex>=list.length)state.stepIndex=list.length-1;const s=list[state.stepIndex],pct=Math.round(((state.stepIndex+1)/list.length)*100);
  $("#flowTitle").textContent=state.template.title;$("#flowCounter").textContent=`${state.stepIndex+1} / ${list.length} adım`;$("#flowPct").textContent=`%${pct}`;$("#flowBar").style.width=`${pct}%`;
  s.type==="photo-form"?renderPhotoForm(s):renderChecklist(s)
}
async function renderPhotoForm(s){
  $("#stage").innerHTML=`<div class="camera-box"><video id="cam" autoplay playsinline muted></video><div class="frame"></div></div><div class="stage-card"><span class="step-label">FOTOĞRAF + MANUEL GİRİŞ</span><h2>${esc(s.category)}</h2><p>${esc(s.instruction)}</p><div class="tip">${esc(s.hint)}</div><div id="photoStatus" class="photo-status ${state.photos[s.id]?"done":""}">${state.photos[s.id]?"✓ Fotoğraf hazır":"Henüz fotoğraf çekilmedi"}</div><div class="actions"><button class="primary" id="shoot" type="button">Fotoğraf çek</button><button class="secondary" id="galleryButton" type="button">Galeriden seç</button><input id="cameraPick" class="native-file-input" type="file" accept="image/*" capture="environment" aria-label="Kameradan fotoğraf çek"><input id="pick" class="native-file-input" type="file" accept="image/*" aria-label="Galeriden fotoğraf seç"></div><div class="manual-fields">${s.fields.map(([k,l,p])=>`<div class="manual-field"><label>${esc(l)}</label><input data-key="${k}" value="${attr(state.values[k]||"")}" placeholder="${attr(p)}"></div>`).join("")}</div><div class="actions"><button class="primary" id="continue">Kaydet ve devam et</button><button class="secondary" id="saveProgress">Taslak kaydet</button></div></div>`;
  document.querySelectorAll("[data-key]").forEach(i=>i.oninput=()=>state.values[i.dataset.key]=i.value.trim());
  const galleryInput=$("#pick"),cameraInput=$("#cameraPick");
  $("#galleryButton").onclick=()=>galleryInput.click();
  $("#shoot").onclick=()=>{const v=$("#cam");if(v&&v.videoWidth)capture();else cameraInput.click()};
  galleryInput.onchange=e=>{const file=e.target.files&&e.target.files[0];if(file)savePhoto(file,s);e.target.value=""};
  cameraInput.onchange=e=>{const file=e.target.files&&e.target.files[0];if(file)savePhoto(file,s);e.target.value=""};
  $("#continue").onclick=()=>{if(!state.photos[s.id])return alert("Fotoğraf çekin veya galeriden seçin.");const miss=s.fields.filter(([k])=>!String(state.values[k]||"").trim());if(miss.length)return alert("Tüm alanları doldurun.");nextStep()};
  $("#saveProgress").onclick=saveCurrentDraft;await startCamera()
}
function renderChecklist(s){
  stopCamera();$("#stage").innerHTML=`<div class="stage-card"><span class="step-label">CHECKLIST</span><h2>${esc(s.category)}</h2><p>Tüm maddeleri Var/Yok olarak işaretleyin.</p><div class="check-list">${s.items.map(([k,l])=>`<div class="check-item"><span>${esc(l)}</span><div class="toggle"><button class="yes ${state.values[k]==="Mevcut"?"active":""}" data-k="${k}" data-v="Mevcut">✓ Var</button><button class="no ${state.values[k]==="Mevcut değil"?"active":""}" data-k="${k}" data-v="Mevcut değil">✕ Yok</button></div></div>`).join("")}</div><div class="actions"><button class="primary" id="continue">Devam et</button><button class="secondary" id="saveProgress">Taslak kaydet</button></div></div>`;
  document.querySelectorAll(".toggle button").forEach(b=>b.onclick=()=>{state.values[b.dataset.k]=b.dataset.v;b.parentElement.querySelectorAll("button").forEach(x=>x.classList.remove("active"));b.classList.add("active")});
  $("#continue").onclick=()=>{if(s.items.some(([k])=>!state.values[k]))return alert("Tüm maddeleri işaretleyin.");nextStep()};$("#saveProgress").onclick=saveCurrentDraft
}
async function startCamera(){stopCamera();try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"},width:{ideal:1920},height:{ideal:1080}},audio:false});$("#cam").srcObject=state.stream}catch(e){}}
function stopCamera(){if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null}}
async function capture(){const v=$("#cam");if(!v||!v.videoWidth)return alert("Kamera hazır değil.");const c=document.createElement("canvas");c.width=v.videoWidth;c.height=v.videoHeight;c.getContext("2d").drawImage(v,0,0);await savePhoto(c,activeSteps()[state.stepIndex])}
async function savePhoto(source,s){let img=source;if(source instanceof File){img=new Image();img.src=URL.createObjectURL(source);await img.decode()}const w=img.naturalWidth||img.width,h=img.naturalHeight||img.height,scale=Math.min(1,1600/w),c=document.createElement("canvas");c.width=Math.round(w*scale);c.height=Math.round(h*scale);c.getContext("2d").drawImage(img,0,0,w,h,0,0,c.width,c.height);state.photos[s.id]={category:s.category,dataUrl:c.toDataURL("image/jpeg",.76)};$("#photoStatus").textContent="✓ Fotoğraf hazır";$("#photoStatus").classList.add("done")}
function nextStep(){stopCamera();state.stepIndex++;if(state.stepIndex>=activeSteps().length){applyDefaults();renderReview();show("review")}else renderFlow()}
function applyDefaults(){state.values.inspectionDate||=new Date().toLocaleDateString("tr-TR");state.values.flameDetectorType||=state.values.flameDetector==="Mevcut"?"Fotosel":"";state.values.finalResult||="Geçti"}
function visibleGroups(){return reviewGroups.filter(([g])=>!(state.template.fuel==="oil"&&g==="Doğalgaz ekipmanları")&&!((state.template.fuel==="gas"||state.template.fuel==="gas-basic")&&g==="Sıvı yakıt ekipmanları"))}
function renderReview(){
  $("#reviewTitle").textContent=state.template.title;let html="";for(const[g,fields]of visibleGroups()){html+=`<div class="group-title">${esc(g)}</div>`+fields.map(([k,l])=>`<div class="field"><label>${esc(l)}</label>${k==="notes"?`<textarea data-review="${k}">${esc(state.values[k]||"")}</textarea>`:`<input data-review="${k}" value="${attr(state.values[k]||"")}">`}</div>`).join("")}html+=`<div class="group-title">Kategori fotoğrafları</div>`+Object.values(state.photos).map(p=>`<div class="field"><label>${esc(p.category)}</label><img class="review-photo" src="${p.dataUrl}"></div>`).join("");$("#reviewFields").innerHTML=html;document.querySelectorAll("[data-review]").forEach(i=>i.oninput=()=>state.values[i.dataset.review]=i.value)
}
function buildRecord(status){return{id:state.recordId,reportNo:state.reportNo,templateId:state.template.id,templateTitle:state.template.title,brand:state.template.brand,series:state.template.series,family:state.template.family,status,stepIndex:state.stepIndex,values:state.values,photos:state.photos,createdAt:state.values._createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),cloudBackedUp:false}}
async function saveCurrentDraft(){state.values._createdAt||=new Date().toISOString();await db.put(buildRecord("draft"));toast("Taslak kaydedildi");await refreshDashboard()}
async function complete(){applyDefaults();state.status="completed";const r=buildRecord("completed");await db.put(r);if(isFirebaseReady()&&navigator.onLine){try{await saveRecordToCloud(r);r.cloudBackedUp=true;await db.put(r)}catch(e){console.warn("Otomatik Firestore kaydı başarısız",e)}}renderReport(r);show("report");await refreshDashboard()}
function renderReport(record){
  const expected={...(state.template.expected||{})};
  const table=(fields,options={})=>{
    const expectedCol=Boolean(options.expectedCol);
    const valueHeader=options.valueHeader===undefined?"Tespit / Ölçülen":options.valueHeader;
    return `<table class="report-table"><tr><th>Açıklama</th>${expectedCol?"<th>Datasheet / Öngörülen</th>":""}<th>${esc(valueHeader)}</th></tr>${fields.map(([k,l])=>`<tr><td>${esc(l)}</td>${expectedCol?`<td>${esc(expected[k]||"-")}</td>`:""}<td class="${state.values[k]==="Mevcut"?"ok":state.values[k]==="Mevcut değil"?"bad":""}">${esc(state.values[k]||"-")}</td></tr>`).join("")}</table>`;
  };
  const sections=visibleGroups().map(([g,f])=>{
    const options=g==="Montaj plakası, conta ve namlu"?{expectedCol:true}:g==="Genel bilgiler"?{valueHeader:""}:{};
    return `<section class="report-section"><h3>${esc(g)}</h3>${table(f,options)}</section>`;
  }).join("");
  const spec=burnerSpecLibrary[state.template.specKey]||{};
  const datasheetRows=datasheetFieldDefinitions.map(([k,label,code])=>`<tr><td><b>${esc(code)}</b></td><td>${esc(label)}</td><td>${esc(expected[k]||"-")}</td><td>${esc(state.values[k]||"-")}</td></tr>`).join("");
  const dimensionRows=fullDimensionDefinitions.filter(([k])=>spec[k]).map(([k,label])=>`<tr><td><b>${esc(label)}</b></td><td>${esc(spec[k])}</td></tr>`).join("");
  const flangeRows=flangeDimensionDefinitions.filter(([k])=>spec[k]).map(([k,label])=>`<tr><td><b>${esc(label)}</b></td><td>${esc(spec[k])}</td></tr>`).join("");
  const packagingRows=packagingDimensionDefinitions.filter(([k])=>spec[k]).map(([k,label])=>`<tr><td><b>${esc(label)}</b></td><td>${esc(spec[k])}</td></tr>`).join("");
  const allDimensions=dimensionRows?`<h4 class="datasheet-subtitle">Katalogdaki tüm brülör boyutları</h4><table class="report-table compact-dimension-table"><tr><th>Ölçü kodu</th><th>Değer</th></tr>${dimensionRows}</table>`:`<div class="datasheet-image-missing">Bu modelin ölçü satırı kaynak katalogda boş bırakılmıştır. Teknik çizim aşağıda gösterilir; değerler manuel ölçülmelidir.</div>`;
  const flangeTable=flangeRows?`<h4 class="datasheet-subtitle">Brülör / kazan flanşı</h4><table class="report-table compact-dimension-table"><tr><th>Ölçü</th><th>Değer</th></tr>${flangeRows}</table>`:"";
  const packagingTable=packagingRows?`<h4 class="datasheet-subtitle">Paketleme boyutları</h4><table class="report-table compact-dimension-table"><tr><th>Ölçü</th><th>Değer</th></tr>${packagingRows}</table>`:"";
  const datasheetImage=state.template.remoteDrawingDataUrl||datasheetImageByTemplate[state.template.datasheetKey||state.template.id]||"";
  const datasheetVisual=datasheetImage?`<figure class="datasheet-visual"><img loading="eager" decoding="sync" src="${esc(datasheetImage)}" alt="${esc(state.template.title)} katalog teknik ölçü çizimi"><figcaption>${esc(state.template.title)} için kaynak katalogdaki gerçek teknik resim ve boyut tablosu</figcaption></figure>`:`<div class="datasheet-image-missing">Bu model için teknik ölçü görseli veri setine henüz eklenmemiştir.</div>`;
  const sourceText=spec.source?`${spec.source}${spec.page?` · Sayfa ${spec.page}`:""}`:datasheetDatasetMeta.source;
  const datasheetSection=`<section class="report-section datasheet-section"><h3>DATASHEET'TEN ALINAN BİLGİLER</h3><p class="datasheet-note">Marka: <b>${esc(state.template.brand||"-")}</b> · Seçili model: <b>${esc(state.template.title)}</b> · Ürün kodu: <b>${esc(state.template.code||"-")}</b>. Teknik resim doğrudan üretici kataloğunun brülör boyutları sayfasından alınmıştır.</p>${datasheetVisual}${allDimensions}${flangeTable}${packagingTable}<h4 class="datasheet-subtitle">Kontrol formunda karşılaştırılan ölçüler</h4><table class="report-table datasheet-table"><tr><th>Kod</th><th>Ölçü açıklaması</th><th>Datasheet değeri</th><th>Sahada ölçülen gerçek değer</th></tr>${datasheetRows}</table><p class="datasheet-source">Kaynak: ${esc(sourceText)} · Veri seti güncellemesi: ${esc(datasheetDatasetMeta.updatedAt)}${spec.note?`<br>Not: ${esc(spec.note)}`:""}</p></section>`;
  const photos=Object.values(state.photos).map((p,i)=>`<section class="photo-report-section"><div class="photo-category-head"><span>${String(i+1).padStart(2,"0")}</span><h3>${esc(p.category)}</h3></div><img src="${p.dataUrl}"></section>`).join("");
  const logo=document.querySelector(".hero-brand img")?.src||"";
  $("#paper").innerHTML=`<div class="report-head"><div class="report-brand-lockup">${logo?`<img src="${logo}">`:""}<div class="report-brand-text">ENORPA</div></div><h1>BRÜLÖR KONTROL FORMU</h1><p>${esc(state.template.title)} [${esc(state.template.code)}] · Proje Numarası: ${esc(state.values.projectNo||"-")}</p></div>${sections}${datasheetSection}<section class="report-section"><h3>EKLER – KATEGORİ FOTOĞRAFLARI</h3>${photos}</section><div id="printFooters" aria-hidden="true"></div>`;
  preparePrintFooters();
}
async function waitForReportImages(){
  const paper=$("#paper");
  if(!paper)return;
  const images=[...paper.querySelectorAll("img")];
  await Promise.all(images.map(img=>{
    if(img.complete&&img.naturalWidth>0)return Promise.resolve();
    if(typeof img.decode==="function")return img.decode().catch(()=>undefined);
    return new Promise(resolve=>{
      const done=()=>resolve();
      img.addEventListener("load",done,{once:true});
      img.addEventListener("error",done,{once:true});
      setTimeout(done,2500);
    });
  }));
}
function preparePrintFooters(){
  const paper=$("#paper"),holder=$("#printFooters");if(!paper||!holder)return;
  holder.innerHTML="";
  requestAnimationFrame(()=>{
    const printableHeight=1040;
    const total=Math.max(1,Math.ceil((paper.scrollHeight+30)/printableHeight));
    paper.style.setProperty("--print-pages",total);
    for(let i=1;i<=total;i++){
      const footer=document.createElement("div");footer.className="print-page-footer";footer.style.top=`${i*printableHeight-34}px`;footer.innerHTML=`<span>saha@enorpa.com</span><b>${i} | ${total}</b>`;holder.appendChild(footer);
    }
  });
}

async function refreshDashboard(){
  const records=await allAvailableRecords(),completed=records.filter(r=>r.status==="completed"),drafts=records.filter(r=>r.status==="draft"),month=new Date().toISOString().slice(0,7);
  $("#statCompleted").textContent=completed.length;$("#statMonth").textContent=completed.filter(r=>r.updatedAt.slice(0,7)===month).length;$("#statPhotos").textContent=records.reduce((n,r)=>n+Object.keys(r.photos||{}).length,0);$("#draftCountText").textContent=`${drafts.length} kayıt`;$("#statCloud").textContent=isFirebaseReady()?"Hazır":"Kapalı";
  $("#recentReports").innerHTML=records.length?records.slice(0,4).map(recordCard).join(""):`<div class="empty-state">Henüz rapor bulunmuyor.</div>`;wireRecordButtons()
}
function recordCard(r){return`<article class="record-card"><div class="record-card-head"><div><strong>${esc(r.templateTitle)}</strong><small>Proje: ${esc(r.values?.projectNo||r.reportNo||"-")}${r.cloudBackedUp||r.cloudOnly?" · ☁ Firestore":""}</small></div><span class="status-badge ${r.status==="completed"?"status-completed":"status-draft"}">${r.status==="completed"?"Tamamlandı":"Devam ediyor"}</span></div><div class="record-meta"><div><span>Seri No</span><b>${esc(r.values?.burnerSerial||"-")}</b></div><div><span>Tarih</span><b>${new Date(r.updatedAt).toLocaleDateString("tr-TR")}</b></div></div><div class="record-actions"><button data-open="${r.id}">Aç</button>${r.status==="draft"&&!r.cloudOnly?`<button data-resume="${r.id}">Devam et</button>`:""}<button data-delete="${r.id}">Sil</button></div></article>`}
function wireRecordButtons(){document.querySelectorAll("[data-open]").forEach(b=>b.onclick=async()=>{const r=(await db.get(b.dataset.open))||(await allAvailableRecords()).find(x=>x.id===b.dataset.open);if(!r)return;renderRecord(r);show("record")});document.querySelectorAll("[data-resume]").forEach(b=>b.onclick=()=>resumeRecord(b.dataset.resume));document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=async()=>{if(confirm("Bu kayıt cihazdan ve Firestore arşivinden silinsin mi?")){await db.delete(b.dataset.delete);if(isFirebaseReady()&&navigator.onLine){try{await getFirestore().collection("burnerReports").doc(b.dataset.delete).delete()}catch(e){console.warn(e)}}await refreshDashboard();renderArchive()}})}
async function renderArchive(){const q=($("#archiveSearch")?.value||"").toLowerCase(),filter=$("#archiveFilter")?.value||"all";let rows=await allAvailableRecords();if(filter!=="all")rows=rows.filter(r=>r.status===filter);if(q)rows=rows.filter(r=>`${r.values?.projectNo||""} ${r.reportNo||""} ${r.templateTitle} ${r.values?.burnerSerial||""} ${r.values?.burnerModel||""}`.toLowerCase().includes(q));$("#archiveList").innerHTML=rows.length?rows.map(recordCard).join(""):`<div class="empty-state">Kayıt bulunamadı.</div>`;wireRecordButtons()}
function renderRecord(r){$("#recordTitle").textContent=r.values?.projectNo||r.reportNo||"Kayıt";$("#recordBody").innerHTML=`<article class="record-detail-card"><h3>${esc(r.templateTitle)}</h3><div class="detail-grid"><div><span>Proje Numarası</span><b>${esc(r.values?.projectNo||"-")}</b></div><div><span>Durum</span><b>${r.status==="completed"?"Tamamlandı":"Devam ediyor"}</b></div><div><span>Seri No</span><b>${esc(r.values?.burnerSerial||"-")}</b></div><div><span>Model</span><b>${esc(r.values?.burnerName||"-")}</b></div><div><span>Tarih</span><b>${new Date(r.updatedAt).toLocaleDateString("tr-TR")}</b></div></div></article><article class="record-detail-card"><h3>Fotoğraflar</h3>${Object.values(r.photos||{}).map(p=>`<div class="field"><label>${esc(p.category)}</label><img class="review-photo" src="${p.dataUrl}"></div>`).join("")||(r.cloudOnly?"Fotoğraflar güvenlik ve ücretsiz kullanım için yalnızca çekimin yapıldığı cihazda tutulur.":"Fotoğraf yok.")}</article><div class="sticky-actions">${r.status==="draft"?`<button class="primary-button" id="resumeDetail">Devam et</button>`:""}<button class="secondary-button" id="openPdfDetail">PDF önizleme</button></div>`;if($("#resumeDetail"))$("#resumeDetail").onclick=()=>resumeRecord(r.id);$("#openPdfDetail").onclick=()=>{state.template=getTemplateById(r.templateId);state.values=r.values;state.photos=r.photos;state.reportNo=r.reportNo;state.recordId=r.id;renderReport(r);show("report")}}
function isFirebaseReady(){return window.firebase&&window.ENORPA_FIREBASE_CONFIG&&window.ENORPA_FIREBASE_CONFIG.apiKey&&!window.ENORPA_FIREBASE_CONFIG.apiKey.includes("BURAYA")}
let firestoreInstance=null;
function getFirestore(){
  if(!isFirebaseReady())throw new Error("Firebase yapılandırması bulunamadı.");
  if(!firestoreInstance){const app=firebase.apps.length?firebase.app():firebase.initializeApp(window.ENORPA_FIREBASE_CONFIG);firestoreInstance=app.firestore()}
  return firestoreInstance
}

async function syncBurnerCatalog(){
  if(!isFirebaseReady()||!navigator.onLine)return;
  try{
    const snap=await getFirestore().collection("burners").where("active","==",true).get();
    const remote=snap.docs.map(doc=>{
      const d=doc.data()||{};
      const family=(d.series||d.brand||"Genel").replace(/\s+Serisi$/i,"").toUpperCase();
      const remoteSpecKey=`firestore-spec-${doc.id}`;
      burnerSpecLibrary[remoteSpecKey]={...(d.dimensions||{}),source:"Yönetim paneli",status:"Yönetici tarafından girildi",note:""};
      return {
        id:`firestore-${doc.id}`,
        firestoreId:doc.id,
        brand:d.brand||"Diğer",
        series:d.series||"Genel",
        family,
        title:d.model||"İsimsiz model",
        code:d.productCode||"",
        fuel:d.fuel||"dual",
        head:d.head||null,
        specKey:remoteSpecKey,
        expected:buildExpectedMeasurements(remoteSpecKey,d.head||null),
        datasheetFileId:d.datasheetFileId||null,
        drawingFileId:d.drawingFileId||null,
        hasDatasheet:!!d.datasheetFileId,
        dataStatus:"Yönetim panelinden eklendi",
        version:"Firestore",
        hidden:false
      };
    });
    const remoteKeys=new Set(remote.map(t=>`${t.brand}|${t.series}|${t.title}|${t.code}`.toLocaleLowerCase("tr-TR")));
    burnerTemplates=burnerTemplates.filter(t=>!remoteKeys.has(`${t.brand}|${t.series}|${t.title}|${t.code}`.toLocaleLowerCase("tr-TR"))).concat(remote);
    renderBrands();
    if(document.querySelector("#templates.active"))renderTemplates();
  }catch(error){console.warn("Firestore brülör kataloğu alınamadı; yerel katalog kullanılıyor.",error)}
}

const catalogFileCache=new Map();
async function loadCatalogFileAsDataUrl(fileId){
  if(catalogFileCache.has(fileId))return catalogFileCache.get(fileId);
  const fileDoc=await getFirestore().collection("burnerFiles").doc(fileId).get();
  if(!fileDoc.exists)throw new Error("Ölçü görseli bulunamadı.");
  const meta=fileDoc.data();
  const snap=await fileDoc.ref.collection("chunks").orderBy("index").get();
  const parts=snap.docs.map(doc=>doc.data().data.toUint8Array());
  if(parts.length!==meta.chunkCount)throw new Error("Ölçü görselinin parçaları eksik.");
  const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(new Blob(parts,{type:meta.type||"image/jpeg"}))});
  catalogFileCache.set(fileId,dataUrl);
  return dataUrl
}
function cloudSafeRecord(record){
  const clean=JSON.parse(JSON.stringify(record));
  delete clean.photos;
  clean.photoCount=Object.keys(record.photos||{}).length;
  clean.cloudBackedUp=true;
  clean.cloudUpdatedAt=new Date().toISOString();
  clean.storageMode="device-only";
  return clean
}
async function saveRecordToCloud(record){
  const cloudRecord=cloudSafeRecord(record);
  await getFirestore().collection("burnerReports").doc(record.id).set(cloudRecord,{merge:true});
  return cloudRecord
}
async function cloudBackup(){
  if(!isFirebaseReady())return alert("Firebase bağlantısı hazır değil. firebase-config.js dosyasını kontrol edin.");
  const button=$("#cloudBackup");const oldText=button.textContent;button.disabled=true;button.textContent="Kaydediliyor…";
  try{
    const r=await db.get(state.recordId)||buildRecord(state.status||"completed");
    await saveRecordToCloud(r);r.cloudBackedUp=true;r.cloudUpdatedAt=new Date().toISOString();await db.put(r);
    toast("Rapor bilgileri Firestore'a kaydedildi. Fotoğraflar cihazda kaldı.");await refreshDashboard()
  }catch(e){console.error(e);alert("Buluta kayıt başarısız: "+(e.message||e))}
  finally{button.disabled=false;button.textContent=oldText}
}
async function fetchCloudRecords(){
  if(!isFirebaseReady()||!navigator.onLine)return[];
  try{const snap=await getFirestore().collection("burnerReports").orderBy("updatedAt","desc").limit(250).get();return snap.docs.map(d=>({...d.data(),id:d.id,photos:{},cloudOnly:true}))}
  catch(e){console.warn("Firestore kayıtları alınamadı",e);return[]}
}
function mergeRecords(localRows,cloudRows){
  const map=new Map();
  cloudRows.forEach(r=>map.set(r.id,r));
  localRows.forEach(r=>{const cloud=map.get(r.id);map.set(r.id,cloud&&new Date(cloud.updatedAt)>new Date(r.updatedAt)?{...cloud,photos:r.photos||{},cloudOnly:false}:{...cloud,...r,photos:r.photos||{},cloudOnly:false})});
  return [...map.values()].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt))
}
async function allAvailableRecords(){return mergeRecords(await db.all(),await fetchCloudRecords())}
async function searchSerial(){
  const q=$("#serialSearch").value.trim().toLowerCase();
  if(!q){$("#searchResults").innerHTML=`<div class="empty-state">Seri numarası yazın.</div>`;return}
  $("#searchResults").innerHTML=`<div class="empty-state">Aranıyor…</div>`;
  const rows=(await allAvailableRecords()).filter(r=>(r.values?.burnerSerial||"").toLowerCase().includes(q));
  $("#searchResults").innerHTML=rows.length?rows.map(recordCard).join(""):`<div class="empty-state">Seri numarası bulunamadı.</div>`;wireRecordButtons()
}

$("#newReport").onclick=()=>{state.selectedBrand=null;show("brands");renderBrands()};$("#continueReport").onclick=()=>{show("archive");$("#archiveFilter").value="draft";renderArchive()};$("#openArchive").onclick=()=>{show("archive");renderArchive()};$("#searchButton").onclick=searchSerial;$("#serialSearch").onkeydown=e=>{if(e.key==="Enter")searchSerial()};$("#archiveSearch").oninput=renderArchive;$("#archiveFilter").onchange=renderArchive;$("#templateSearch").oninput=renderTemplates;$("#seriesFilter").onchange=renderTemplates;
document.querySelectorAll("[data-back]").forEach(b=>b.onclick=()=>show(b.dataset.back));$("#flowBack").onclick=()=>{stopCamera();if(state.stepIndex>0){state.stepIndex--;renderFlow()}else show("templates")};$("#reviewBack").onclick=()=>{state.stepIndex=activeSteps().length-1;show("flow");renderFlow()};$("#saveDraft").onclick=saveCurrentDraft;$("#completeReport").onclick=complete;$("#reportBack").onclick=()=>show("review");$("#printReport").onclick=async()=>{await waitForReportImages();preparePrintFooters();setTimeout(()=>window.print(),120)};$("#cloudBackup").onclick=cloudBackup;
addEventListener("beforeprint",preparePrintFooters);renderBrands();syncBurnerCatalog();refreshDashboard();if("serviceWorker"in navigator)addEventListener("load",()=>navigator.serviceWorker.register("sw.js").catch(()=>{}));
